package online.wanan.xingchen.config;
import org.springframework.boot.ApplicationRunner;import org.springframework.context.annotation.*;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.security.crypto.password.PasswordEncoder;import java.time.Instant;
/** Secondary disposable account for isolated browser password-rotation tests only. */
@Configuration(proxyBeanMethods=false) @Profile("model-fake-e2e") public class FakeAdminE2eConfiguration {
 @Bean @org.springframework.core.annotation.Order(org.springframework.core.Ordered.LOWEST_PRECEDENCE) ApplicationRunner seedSecondaryFakeAdmin(JdbcTemplate jdbc,PasswordEncoder encoder){return args->{String primaryUser=System.getenv().getOrDefault("XINGCHEN_CONSOLE_ADMIN_USER","");String primaryPassword=System.getenv().getOrDefault("XINGCHEN_CONSOLE_ADMIN_PASSWORD","");var primaryHash=jdbc.query("SELECT password_hash FROM console_admin_credentials WHERE username=?",rs->rs.next()?rs.getString(1):null,primaryUser);if(primaryHash==null||!encoder.matches(primaryPassword,primaryHash))throw new IllegalStateException("Primary E2E admin bootstrap verification failed");String username=System.getenv().getOrDefault("XINGCHEN_E2E_SECONDARY_USER","");String password=System.getenv().getOrDefault("XINGCHEN_E2E_SECONDARY_PASSWORD","");if(username.isBlank()&&password.isBlank())return;if(username.isBlank()||password.length()<14||password.getBytes(java.nio.charset.StandardCharsets.UTF_8).length>72)throw new IllegalStateException("Invalid disposable E2E admin configuration");if(jdbc.queryForObject("SELECT COUNT(*) FROM console_admin_credentials WHERE username=?",Integer.class,username)==0){String now=Instant.now().toString();jdbc.update("INSERT INTO console_admin_credentials(username,password_hash,created_at,updated_at) VALUES(?,?,?,?)",username,encoder.encode(password),now,now);}};}
}
